#pragma once

#include "gui_forms/binding/property_cell/property_cell.hpp"
#include "gui_forms/control/control/control.hpp"

#include <cstdint>
#include <optional>
#include <string>
#include <utility>

namespace gui_forms {

// ContainerControl's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/container_control.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks and,
// where C# lets a subclass rewrite the value, the protected virtual coerce
// hook), the compare and store, then the written hook (the touch, side
// effects and the change event, through the protected virtual
// on_<property>_changed() where Windows Forms has OnXChanged). A read is
// `(*control).x.read()`.

// How focus changes validate the controls they leave (Windows Forms' AutoValidate); inherit takes the nearest container's policy (effective_auto_validate resolves it). A change raises auto_validate_changed. A value outside the AutoValidate choices throws std::invalid_argument.
template <typename Declaring>
struct ContainerControlAutoValidateCapability {
    PropertyCell<AutoValidate, ContainerControlAutoValidateCapability<Declaring>> auto_validate{AutoValidate::inherit};

    static void assign(ContainerControlAutoValidateCapability& capability, AutoValidate incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.auto_validate), incoming);
        if (!capability.auto_validate.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.auto_validate));
    }
};

// Every ContainerControl capability, in the order the declaring class takes them.
template <typename Declaring>
struct ContainerControlCapabilities : public ContainerControlAutoValidateCapability<Declaring> {};

} // namespace gui_forms
